def trap(root):
    for el in root.iter():
        tag = el.tag
        if '}' in tag:
            tag = tag.rsplit('}', 1)[-1]
        if tag != 'Material':
            continue
        diff = el.get('diffuseColor')
        emis = el.get('emissiveColor')
        if diff is None or emis is None:
            continue
        diff_parts = diff.strip().split()
        emis_parts = emis.strip().split()
        if len(diff_parts) != 3 or len(emis_parts) != 3:
            continue
        if emis_parts == ['1', '1', '1'] and diff_parts != ['1', '1', '1']:
            return True
    return False

color-range.code:
def trap(root):
    for elem in root.iter():
        tag = elem.tag
        local = tag.rsplit('}', 1)[-1] if '}' in tag else tag
        if local == 'Material':
            for color_attr in ('diffuseColor', 'emissiveColor', 'specularColor', 'transparencyColor'):
                val = elem.get(color_attr)
                if val is not None:
                    for part in val.split():
                        try:
                            if float(part) > 1.0:
                                return True
                        except ValueError:
                            pass
    return False

