route-undefined.code:
def trap(root):
    defined = set()
    for elem in root.iter():
        if 'DEF' in elem.attrib:
            defined.add(elem.attrib['DEF'])
    for elem in root.iter():
        tag = elem.tag.rsplit('}', 1)[-1] if '}' in elem.tag else elem.tag
        if tag == 'ROUTE':
            for attr in ('fromNode', 'toNode'):
                if attr in elem.attrib:
                    ref = elem.attrib[attr]
                    if ref not in defined:
                        return True
    return False

